// Generated by GitHub Copilot - Oct-02-2026
import { useMemo, useState } from 'react';
import type { Race, Source } from '../types';
import { SENATE_BASELINE, SENATE_MAJORITY } from '../config';
import { raceProbability, senateOutlook, type Winner } from '../lib/analysis';
import { SOURCE_COLOR, pct } from '../lib/format';

type Choice = Winner | 'auto';

function Segmented({ race, value, onChange }: { race: Race; value: Choice; onChange: (c: Choice) => void }) {
  const opts: { v: Choice; label: string; aria: string; on: string }[] = [
    { v: 'D', label: 'D', aria: `${race.dem} wins ${race.name}`, on: 'bg-dem text-white' },
    { v: 'auto', label: 'Odds', aria: `Use market odds for ${race.name}`, on: 'bg-white/15 text-white' },
    { v: 'R', label: 'R', aria: `${race.rep} wins ${race.name}`, on: 'bg-rep text-white' },
  ];
  return (
    <div role="group" aria-label={`${race.name} outcome`} className="inline-flex shrink-0 rounded-lg border border-line p-0.5 text-xs">
      {opts.map((o) => (
        <button
          key={o.v}
          type="button"
          aria-pressed={value === o.v}
          aria-label={o.aria}
          onClick={() => onChange(o.v)}
          className={`min-w-9 rounded-md px-2 py-1.5 font-semibold transition-colors ${value === o.v ? o.on : 'text-muted hover:text-gray-200'}`}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

function RaceBar({ race, p, choice }: { race: Race; p: number; choice: Choice }) {
  const shown = choice === 'D' ? 1 : choice === 'R' ? 0 : p;
  return (
    <div className="relative mt-1.5 h-2 overflow-hidden rounded-full bg-rep/60" aria-hidden="true">
      <div className="h-full bg-dem transition-[width] duration-300" style={{ width: `${shown * 100}%` }} />
      <div className="absolute top-0 bottom-0 w-px bg-ink" style={{ left: '50%' }} />
      {choice === 'auto' &&
        (['kalshi', 'polymarket'] as const).map((id) =>
          race[id] === null ? null : (
            <span
              key={id}
              className="absolute top-0 bottom-0 w-0.5"
              style={{ left: `${race[id]! * 100}%`, background: SOURCE_COLOR[id] }}
            />
          ),
        )}
    </div>
  );
}

/** Interactive Senate path: ranks key races by Democratic odds and recomputes majority odds from user picks. */
export function SenatePath({ races, sources }: { races: readonly Race[]; sources: readonly Source[] }) {
  const [picks, setPicks] = useState<Record<string, Winner>>({});
  const outlook = useMemo(() => senateOutlook(races, picks), [races, picks]);
  const ranked = useMemo(
    () =>
      races
        .map((r) => ({ race: r, p: raceProbability(r) }))
        .filter((x): x is { race: Race; p: number } => x.p !== null)
        .sort((a, b) => b.p - a.p),
    [races],
  );
  const marketSenate = useMemo(() => {
    const v = sources.filter((s) => s.kind === 'market' && s.status === 'ok' && s.senate !== null).map((s) => s.senate!);
    return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
  }, [sources]);

  const setChoice = (state: string, c: Choice) =>
    setPicks((prev) => {
      const next = { ...prev };
      if (c === 'auto') delete next[state];
      else next[state] = c;
      return next;
    });
  const hasPicks = Object.keys(picks).length > 0;
  const demSeats = outlook.favoriteSeats;
  const majority = demSeats >= SENATE_MAJORITY;
  const maxDist = Math.max(...outlook.dist);

  return (
    <section aria-labelledby="senate-title" className="panel p-5 sm:p-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 id="senate-title" className="text-lg font-semibold text-white">
            The bottleneck: Senate seat #51
          </h2>
          <p className="mt-1 text-sm text-muted">
            Democrats hold {SENATE_BASELINE.dem} seats outside these races and need {outlook.needed} of {ranked.length}. Pick winners to test scenarios.
          </p>
        </div>
        {hasPicks && (
          <button type="button" onClick={() => setPicks({})} className="rounded-lg border border-line px-3 py-1.5 text-sm text-gray-200 hover:bg-white/5">
            Reset
          </button>
        )}
      </div>

      <div className="mt-5 grid gap-3 sm:grid-cols-3" aria-live="polite">
        <div className="rounded-xl border border-line p-4">
          <p className="text-xs text-muted">Dem seats {hasPicks ? '(picks + favorites)' : '(favorites win)'}</p>
          <p className={`mt-1 text-3xl font-semibold tabular-nums ${majority ? 'text-dem' : 'text-rep'}`}>
            {demSeats}
            <span className="text-base text-muted"> / 100</span>
          </p>
          <p className="text-xs text-muted">{majority ? 'Majority' : `${SENATE_MAJORITY - demSeats} short`}</p>
        </div>
        <div className="rounded-xl border border-line p-4">
          <p className="text-xs text-muted">P(≥ 51) if races independent</p>
          <p className="mt-1 text-3xl font-semibold text-white tabular-nums">{pct(outlook.pMajorityIndependent)}</p>
          <p className="text-xs text-muted">Expected {outlook.expectedSeats.toFixed(1)} seats</p>
        </div>
        <div className="rounded-xl border border-line p-4">
          <p className="text-xs text-muted">Markets: Senate control</p>
          <p className="mt-1 text-3xl font-semibold text-white tabular-nums">{pct(marketSenate)}</p>
          <p className="text-xs text-muted">
            Tipping point: <strong className="text-gray-100">{outlook.tippingPoint ?? '–'}</strong>
          </p>
        </div>
      </div>

      <figure className="mt-5">
        <figcaption className="text-xs text-muted">Distribution of Democratic seats{hasPicks ? ' given your picks' : ''} (independent races)</figcaption>
        <div className="mt-2 flex h-20 items-end gap-1" role="img" aria-label={`Seat distribution; ${pct(outlook.pMajorityIndependent)} chance of 51 or more.`}>
          {outlook.dist.map((d, k) => {
            const seats = outlook.distOffset + k;
            return (
              <div key={seats} className="flex flex-1 flex-col items-center gap-1">
                <div
                  className={`w-full rounded-t ${seats >= SENATE_MAJORITY ? 'bg-dem' : 'bg-rep/70'}`}
                  style={{ height: `${maxDist ? (d / maxDist) * 64 : 0}px` }}
                  title={`${seats} seats: ${pct(d, 1)}`}
                />
                <span className="text-[10px] text-muted tabular-nums">{seats}</span>
              </div>
            );
          })}
        </div>
      </figure>

      <ol className="mt-6 grid gap-1">
        {ranked.map(({ race, p }, i) => {
          const choice: Choice = picks[race.state] ?? 'auto';
          return (
            <li key={race.state}>
              {i === outlook.needed && (
                <div className="my-2 flex items-center gap-2 text-[11px] font-semibold tracking-wide text-amber-300 uppercase" role="separator">
                  <span className="h-px flex-1 bg-amber-300/40" />
                  Majority line · seat 51
                  <span className="h-px flex-1 bg-amber-300/40" />
                </div>
              )}
              <div className={`flex items-center gap-3 rounded-lg px-2 py-2 ${race.state === outlook.tippingPoint ? 'bg-amber-300/5 ring-1 ring-amber-300/30' : ''}`}>
                <span className="w-8 shrink-0 text-center text-xs font-bold text-gray-300">{race.state}</span>
                <div className="min-w-0 flex-1">
                  <div className="flex items-baseline justify-between gap-2 text-sm">
                    <span className="truncate">
                      <span className="text-gray-100">{race.name}</span>
                      <span className="hidden text-muted sm:inline">
                        {' '}· {race.dem} v {race.rep}
                        {race.heldBy === 'R' && <span className="ml-1 rounded bg-rep/20 px-1 text-[10px] text-rep">R-held</span>}
                      </span>
                    </span>
                    <span className="shrink-0 font-semibold tabular-nums">{pct(p)}</span>
                  </div>
                  <RaceBar race={race} p={p} choice={choice} />
                </div>
                <Segmented race={race} value={choice} onChange={(c) => setChoice(race.state, c)} />
              </div>
            </li>
          );
        })}
      </ol>
      <p className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted">
        <span>Bar = mean of Kalshi and Polymarket.</span>
        <span className="inline-flex items-center gap-1"><span className="h-3 w-0.5" style={{ background: SOURCE_COLOR.kalshi }} aria-hidden="true" />Kalshi</span>
        <span className="inline-flex items-center gap-1"><span className="h-3 w-0.5" style={{ background: SOURCE_COLOR.polymarket }} aria-hidden="true" />Polymarket</span>
      </p>
    </section>
  );
}
